/**
 * generate-site-state.mjs
 * Auto-generated by: scripts/generate-site-state.mjs
 * Do NOT edit src/data/site-state.json manually -- run `npm run build` to regenerate.
 *
 * Scans all articles in src/content/ and writes src/data/site-state.json with:
 *   generatedAt, totals, brands[], verdictTotals, priceTierRatio
 *
 * priceTier ("high" | "low") logic:
 *   1. Read priceTier from brand profile frontmatter (src/data/brands/<slug>.md)
 *   2. If not set, use FALLBACK_PRICE_TIERS (hardcoded based on brand's flagship price)
 *   3. Write back to brand profile so future runs use the stored value
 *
 * $150 threshold: brands whose flagship products are priced at or above $150 -> "high"
 */

import { readFileSync, readdirSync, writeFileSync, existsSync } from 'fs';
import { join, resolve } from 'path';
import { fileURLToPath } from 'url';

const rootDir = resolve(fileURLToPath(new URL('.', import.meta.url)), '..');

const CONTENT_DIRS = [
  join(rootDir, 'src', 'content', 'tableware'),
  join(rootDir, 'src', 'content', 'knives'),
  join(rootDir, 'src', 'content', 'kitchen'),
];
const BRANDS_DIR = join(rootDir, 'src', 'data', 'brands');
const OUTPUT_FILE = join(rootDir, 'src', 'data', 'site-state.json');

// Hardcoded fallback priceTier for known brands.
// A brand is "high" if its flagship products are priced at or above $150.
// Only used if priceTier is not already in the brand profile frontmatter.
const FALLBACK_PRICE_TIERS = {
  Noritake:   'low',   // everyday dinnerware $30-$150
  Zojirushi:  'high',  // premium rice cookers $150-$350
  Shun:       'high',  // knives $100-$400
  Hario:      'low',   // coffee accessories $12-$130
  Vermicular: 'high',  // cast iron $200-$500
  Kinto:      'low',   // drinkware $20-$80
  Tiger:      'high',  // premium rice cookers $100-$300
  Miyabi:     'high',  // knives $150-$370
};

// Brand detection: which brand keyword appears earliest in the slug wins.
const BRAND_KEYWORDS = [
  { name: 'Noritake',   keyword: 'noritake'   },
  { name: 'Zojirushi',  keyword: 'zojirushi'  },
  { name: 'Shun',       keyword: 'shun'        },
  { name: 'Hario',      keyword: 'hario'       },
  { name: 'Vermicular', keyword: 'vermicular'  },
  { name: 'Kinto',      keyword: 'kinto'       },
  { name: 'Tiger',      keyword: 'tiger'       },
  { name: 'Miyabi',     keyword: 'miyabi'      },
];

function detectBrand(slug) {
  let earliest = null;
  for (const { name, keyword } of BRAND_KEYWORDS) {
    const idx = slug.indexOf(keyword);
    if (idx !== -1 && (earliest === null || idx < earliest.idx)) {
      earliest = { name, idx };
    }
  }
  return earliest ? earliest.name : 'Unknown';
}

// Split raw markdown into frontmatter string and body string.
function splitContent(raw) {
  const match = raw.match(/^---[\r\n]([\s\S]*?)[\r\n]---[\r\n]?([\s\S]*)$/);
  if (!match) return { frontmatter: '', body: raw };
  return { frontmatter: match[1], body: match[2] };
}

// Extract a top-level YAML scalar by key name.
function yamlScalar(yaml, key) {
  const re = new RegExp(`^${key}:\\s*["']?([^"'\\n]+)["']?`, 'm');
  const m = yaml.match(re);
  return m ? m[1].trim() : null;
}

// Extract verdict.rating from frontmatter.
// Only matches the three allowed values so reviewLog.verdict: "pass" is never returned.
function extractVerdictRating(yaml) {
  const m = yaml.match(/^verdict:[\s\S]*?\n\s{2}rating:\s*["']?(recommended|conditional|not-recommended)["']?/m);
  return m ? m[1] : null;
}

// --- Brand profile helpers ---

function profilePath(brandName) {
  return join(BRANDS_DIR, `${brandName.toLowerCase()}.md`);
}

function readProfilePriceTier(brandName) {
  const p = profilePath(brandName);
  if (!existsSync(p)) return null;
  const { frontmatter } = splitContent(readFileSync(p, 'utf-8'));
  return yamlScalar(frontmatter, 'priceTier');
}

function writeProfilePriceTier(brandName, priceTier) {
  const p = profilePath(brandName);
  if (!existsSync(p)) return;
  let content = readFileSync(p, 'utf-8');
  if (/^priceTier:/m.test(content)) return; // already set

  // Insert priceTier just before the closing --- of the frontmatter.
  // Find the second occurrence of \n--- (the first is the opening ---)
  const openEnd = content.indexOf('---\n') + 3; // past the opening ---
  const closeIdx = content.indexOf('\n---', openEnd);
  if (closeIdx === -1) return;

  content = content.slice(0, closeIdx) + `\npriceTier: "${priceTier}"` + content.slice(closeIdx);
  writeFileSync(p, content, 'utf-8');
  process.stdout.write(`  Wrote priceTier="${priceTier}" -> brands/${brandName.toLowerCase()}.md\n`);
}

// --- Main ---

const brandMap = {};

for (const dir of CONTENT_DIRS) {
  const files = readdirSync(dir).filter(f => f.endsWith('.md')).sort();

  for (const file of files) {
    const slug = file.replace('.md', '');
    const brandName = detectBrand(slug);

    const raw = readFileSync(join(dir, file), 'utf-8');
    const { frontmatter } = splitContent(raw);

    const verdictRating = extractVerdictRating(frontmatter);

    if (!brandMap[brandName]) {
      brandMap[brandName] = {
        name: brandName,
        articles: 0,
        priceTier: null,
        verdicts: { recommended: 0, conditional: 0, notRecommended: 0 },
        slugs: [],
      };
    }

    const brand = brandMap[brandName];
    brand.articles++;
    brand.slugs.push(slug);

    if (verdictRating === 'recommended')     brand.verdicts.recommended++;
    else if (verdictRating === 'conditional') brand.verdicts.conditional++;
    else if (verdictRating === 'not-recommended') brand.verdicts.notRecommended++;
  }
}

// Resolve and write back priceTier for each brand.
for (const [brandName, brand] of Object.entries(brandMap)) {
  let pt = readProfilePriceTier(brandName);

  if (!pt) {
    // Use hardcoded fallback; fall back to 'low' for unknown brands.
    pt = FALLBACK_PRICE_TIERS[brandName] ?? 'low';
    writeProfilePriceTier(brandName, pt);
  }

  brand.priceTier = pt;
}

// Sort brands alphabetically for stable output.
const brands = Object.values(brandMap).sort((a, b) => a.name.localeCompare(b.name));
const totalArticles = brands.reduce((s, b) => s + b.articles, 0);
const brandCount = brands.length;

const verdictTotals = brands.reduce(
  (acc, b) => ({
    recommended:    acc.recommended    + b.verdicts.recommended,
    conditional:    acc.conditional    + b.verdicts.conditional,
    notRecommended: acc.notRecommended + b.verdicts.notRecommended,
  }),
  { recommended: 0, conditional: 0, notRecommended: 0 },
);

const highCount = brands.filter(b => b.priceTier === 'high').length;
const lowCount  = brands.filter(b => b.priceTier === 'low').length;

const siteState = {
  _note: 'Auto-generated by scripts/generate-site-state.mjs -- do not edit manually.',
  generatedAt: new Date().toISOString().slice(0, 10),
  totals: {
    brands: brandCount,
    articles: totalArticles,
    avgPerBrand: parseFloat((totalArticles / brandCount).toFixed(1)),
  },
  brands,
  verdictTotals,
  priceTierRatio: {
    high: highCount,
    low: lowCount,
    ratio: parseFloat((highCount / (highCount + lowCount)).toFixed(2)),
  },
};

writeFileSync(OUTPUT_FILE, JSON.stringify(siteState, null, 2) + '\n', 'utf-8');
process.stdout.write(
  `generate-site-state: OK -- ${totalArticles} articles across ${brandCount} brands\n`,
);
